const alerts = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);

return alerts
  .filter((alert) => alert.severity === 'high' && Number(alert.score_0_100) >= 70)
  .map((alert) => ({
    json: {
      subject: `Swasthya Sentinel high-risk alert: ${alert.location_name}`,
      message: `High-risk geographic alert for ${alert.location_name} (${alert.location_id}), score ${Number(alert.score_0_100).toFixed(1)}/100. Top factors: ${alert.top_factors.map((factor) => `${factor.factor_name} (+${Number(factor.contribution).toFixed(1)} pts)`).join('; ')}. This is synthetic surveillance data and not a diagnosis.`,
      location_id: alert.location_id,
      location_name: alert.location_name,
      score_0_100: alert.score_0_100,
      cluster_id: alert.cluster_id,
      top_factors: alert.top_factors,
      data_mode: alert.data_mode,
      not_a_diagnosis: alert.not_a_diagnosis
    }
  }));
